/* @lc app=leetcode id=4041 lang=kotlin */ class Solution { fun minOperations(nums: IntArray, sum: Int): Int = nums.fold(IntArray(sum + 1) { if (it == 0) 0 else 1_000_000_000 }) { dp, x -> dp.clone().also { nd -> generateSequence(0) { it + 1 }.takeWhile { (x shr it) > 0 }.flatMap { d -> generateSequence(0) { it + 1 }.takeWhile { ((x shr d).toLong() shl it) <= sum }.map { j -> ((x shr d) shl j) to (d + j) } }.forEach { (v, c) -> (0..sum - v).filter { dp[it] != 1_000_000_000 }.forEach { s -> nd[s + v] = minOf(nd[s + v], dp[s] + c) } } } }.let { if (it[sum] >= 1_000_000_000) -1 else it[sum] } }